// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testRegression_property() public {
        address user = address(0x1234);
        address target = address(0x5678);
        vm.deal(user, 1 wei);
        vm.prank(user);
        c.deposit{value: 1 wei}();
        uint256 balanceBefore = address(c).balance;
        vm.prank(address(this));
        c.migrateTo(target);
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == 0 ether);
    }
}
